  ('Q_20261102_14', 'PG', 'IPAS', 'Bunyi dapat merambat melalui…', 'none', '', '["Ruang hampa saja", "Benda padat, cair dan gas", "Cahaya saja", "Ruang kosong tanpa zat perantara"]'::jsonb, '[]'::jsonb, 'Benda padat, cair dan gas', 10, 'Sesuai kunci jawaban.'),
