  ('Q_20261102_17', 'PG', 'IPAS', 'Hewan yang memperoleh makanan dengan memangsa hewan lain adalah ....', 'none', '', '["Sapi", "Kelinci", "Singa", "Kambing"]'::jsonb, '[]'::jsonb, 'Kelinci', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_18', 'PG', 'IPAS', 'Dalam rantai makanan, tumbuhan hijau disebut produsen karena ....', 'none', '', '["Memakan hewan lain", "Dapat membuat makanan sendiri", "Menguraikan bangkai hewan", "Selalu hidup di dalam tanah"]'::jsonb, '[]'::jsonb, 'Dapat membuat makanan sendiri', 10, 'Sesuai kunci jawaban.'),
