  ('Q_20261102_20', 'PG', 'IPAS', 'Jamur dan bakteri memiliki peran penting dalam ekosistem, yaitu sebagai ....', 'none', '', '["Produsen", "Konsumen tingkat pertama", "Dekomposer", "Pemangsa"]'::jsonb, '[]'::jsonb, 'Konsumen tingkat pertama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_21', 'PG', 'IPAS', 'Perhatikan ilustrasi berikut!<br>Seekor kelinci sedang memakan rumput. Berdasarkan gambar tersebut, kelinci termasuk hewan ....', 'image', './assets/soal/soal-0001.jpg', '["Herbivora", "Karnivora", "Omnivora", "Dekomposer"]'::jsonb, '[]'::jsonb, 'Karnivora', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_22', 'PG', 'IPAS', 'Di sebuah sawah terdapat padi, belalang, katak, dan ular. Makhluk hidup yang berperan sebagai produsen adalah ....', 'none', '', '["Katak", "Ular", "Belalang", "Padi"]'::jsonb, '[]'::jsonb, 'Ular', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_23', 'PG', 'IPAS', 'Perhatikan makhluk hidup berikut!<br>Belalang memakan daun tumbuhan untuk memperoleh energi. Dalam rantai makanan, belalang berperan sebagai ....', 'image', './assets/soal/soal-0002.jpg', '["Produsen", "Konsumen tingkat pertama", "Dekomposer", "Pengurai"]'::jsonb, '[]'::jsonb, 'Konsumen tingkat pertama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_24', 'PG', 'IPAS', 'Perhatikan makhluk hidup berikut:<br>Urutan rantai makanan yang benar adalah ....', 'image', 'assets/soal/20261102/image1.jpg', '["Padi", "Tikus", "Ular", "Elang"]'::jsonb, '[]'::jsonb, 'Tikus', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_25', 'PG', 'IPAS', 'Dalam rantai makanan: rumput → belalang → katak → ular, makhluk hidup yang dimakan oleh katak adalah ....', 'none', '', '["Rumput", "Belalang", "Ular", "Jamur"]'::jsonb, '[]'::jsonb, 'Belalang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_26', 'PG', 'IPAS', 'Di suatu padang rumput terjadi kekeringan sehingga jumlah rumput berkurang drastis. Di tempat tersebut terdapat belalang yang memakan rumput dan katak yang memakan belalang.<br>Apa kemungkinan yang terjadi jika rumput semakin sedikit?', 'none', '', '["Jumlah belalang dapat menurun karena kekurangan makanan.", "Jumlah belalang pasti bertambah banyak.", "Jumlah katak tidak akan terpengaruh.", "Semua hewan berubah menjadi produsen."]'::jsonb, '[]'::jsonb, 'Jumlah belalang pasti bertambah banyak.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_27', 'PG', 'IPAS', 'Perhatikan rantai makanan berikut!<br>Rumput → Belalang → Katak → Ular → Elang<br>Jika jumlah katak berkurang secara drastis, kemungkinan yang terjadi adalah ....', 'image', './assets/soal/soal-0003.jpg', '["Jumlah belalang dapat meningkat.", "Jumlah rumput langsung habis karena dimakan ular.", "Jumlah belalang pasti menghilang.", "Jumlah rumput tidak mungkin berubah."]'::jsonb, '[]'::jsonb, 'Jumlah rumput langsung habis karena dimakan ular.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_28', 'PG', 'IPAS', 'Bayangkan dalam suatu lingkungan tidak terdapat jamur dan bakteri pengurai. Banyak daun kering dan bangkai hewan menumpuk di tanah.<br>Apa akibat yang paling mungkin terjadi?', 'none', '', '["Semua tumbuhan langsung tumbuh lebih subur.", "Tidak ada lagi makhluk hidup yang membutuhkan makanan.", "Sisa makhluk hidup sulit terurai sehingga unsur hara tidak kembali ke tanah dengan baik.", "Semua hewan berubah menjadi pengurai."]'::jsonb, '[]'::jsonb, 'Tidak ada lagi makhluk hidup yang membutuhkan makanan.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_29', 'PG', 'IPAS', 'Sekelompok peserta didik mengamati ekosistem sawah. Mereka menemukan padi, tikus, ular, dan elang.<br>Kelompok tersebut membuat empat diagram rantai makanan. Diagram yang paling tepat adalah ....', 'none', '', '["Tikus → Padi → Ular → Elang", "Padi → Tikus → Ular → Elang", "Elang → Ular → Tikus → Padi", "Ular → Elang → Padi → Tikus"]'::jsonb, '[]'::jsonb, 'Padi → Tikus → Ular → Elang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_30', 'PG', 'IPAS', 'Di sebuah sawah, petani menggunakan racun secara berlebihan untuk membunuh semua ular karena dianggap mengganggu. Padahal, ular memakan tikus yang merusak tanaman padi.<br>Menurut pendapatmu, tindakan yang paling tepat untuk menjaga keseimbangan ekosistem sawah adalah ....', 'none', '', '["Membunuh semua hewan yang ada di sawah.", "Menggunakan racun sebanyak mungkin.", "Membiarkan tikus berkembang biak tanpa pengendalian.", "Menjaga keberadaan ular sebagai pemangsa alami tikus dan mengendalikan hama secara bijaksana."]'::jsonb, '[]'::jsonb, 'Menggunakan racun sebanyak mungkin.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261107_01', 'PG', 'PJOK SD', 'Gerakan yang menyebabkan tubuh berpindah dari satu tempat ke tempat lain disebut gerak ....', 'none', '', '["nonlokomotor", "lokomotor", "manipulatif", "diam"]'::jsonb, '[]'::jsonb, 'lokomotor', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261107_02', 'PG', 'PJOK SD', 'Contoh pasangan gerakan lokomotor yang benar adalah ....', 'none', '', '["mengayun dan memutar lengan", "menekuk siku dan meliukkan badan", "berjalan dan berlari", "membungkuk dan meregangkan tangan"]'::jsonb, '[]'::jsonb, 'berjalan dan berlari', 10, 'Sesuai kunci jawaban.'),
