  ('Q_20261107_05', 'PG', 'PJOK SD', 'Setelah melompat melewati rintangan rendah, cara mendarat yang aman adalah ....', 'none', '', '["mendarat dengan lutut lurus dan kaku", "mendarat sambil menutup mata", "mendarat dengan kedua kaki dan lutut sedikit ditekuk", "mendarat sambil mendorong teman"]'::jsonb, '[]'::jsonb, 'mendarat dengan kedua kaki dan lutut sedikit ditekuk', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261107_06', 'PG', 'PJOK SD', 'Sebelum melakukan latihan berlari dan melompat, sebaiknya kita ....', 'none', '', '["melakukan pemanasan", "langsung berlari secepat-cepatnya", "duduk diam sampai lelah", "langsung melakukan pendinginan"]'::jsonb, '[]'::jsonb, 'melakukan pemanasan', 10, 'Sesuai kunci jawaban.'),
